def test_same_frozen_input_produces_the_same_stable_report_digest(
    tmp_path: Path,
) -> None:
    _init_repo(tmp_path)
    _write(tmp_path, "src/app.py", "def _value():\n    return 1\n")
    snapshot = build_source_snapshot(
        SourceSnapshotOptions(root=tmp_path, source_kind="local-unstaged")
    )

    first = _evaluate(tmp_path, scope=("src/app.py",), snapshot=snapshot)
    time.sleep(1.05)
    second = _evaluate(tmp_path, scope=("src/app.py",), snapshot=snapshot)

    assert stable_artifact_digest(first) == stable_artifact_digest(second)


def test_historical_600_line_file_is_advisory_only(tmp_path: Path) -> None:
    _init_repo(tmp_path, {"src/legacy.py": _simple_lines(600)})
    lines = _simple_lines(600).splitlines()
    lines[300] = "value_300 = 999"
    _write(tmp_path, "src/legacy.py", "\n".join(lines) + "\n")

    report = _evaluate(tmp_path, scope=("src/legacy.py",))

    assert _severities(report, "lean.file-budget") == {FindingSeverity.ADVISORY}
    assert report.status == LoopStatus.PASSED


def test_generated_401_line_file_is_not_in_product_budget(tmp_path: Path) -> None:
    _init_repo(tmp_path)
    _write(
        tmp_path,
        "generated/client.py",
        "# Code generated by schema compiler. DO NOT EDIT.\n" + _simple_lines(401),
    )

    report = _evaluate(tmp_path, scope=("generated/client.py",))

    metric = report.metrics.files[0]
    assert metric.classification == "generated"
    assert report.metrics.classification_counts["generated"] == 1
    assert _severities(report, "lean.file-budget") == set()


def test_generated_path_without_provenance_fails_closed(tmp_path: Path) -> None:
    _init_repo(tmp_path)
    _write(tmp_path, "generated/handwritten.py", "def hidden_logic():\n    return 1\n")

    report = _evaluate(tmp_path, scope=("generated/handwritten.py",))

    assert report.metrics.files[0].classification == "unknown"
    assert report.status == LoopStatus.NEEDS_USER


def test_51_line_low_complexity_function_is_advisory(tmp_path: Path) -> None:
    _init_repo(tmp_path)
    body = "\n".join(f"    value += {index}" for index in range(51))
    _write(
        tmp_path,
        "src/app.py",
        f"def _process():\n    value = 0\n{body}\n    return value\n",
    )

    report = _evaluate(tmp_path, scope=("src/app.py",))

    assert _severities(report, "lean.function-budget") == {FindingSeverity.ADVISORY}
    assert report.status == LoopStatus.PASSED


def test_function_risk_uses_only_imports_referenced_by_that_function(
    tmp_path: Path,
) -> None:
    _init_repo(tmp_path)
    imports = "\n".join(f"import dependency_{index}" for index in range(13))
    body = "\n".join(f"    value += {index}" for index in range(51))
    _write(
        tmp_path,
        "src/app.py",
        f"{imports}\n\ndef _process():\n    value = dependency_0.VALUE\n{body}\n"
        "    return value\n",
    )

    report = _evaluate(tmp_path, scope=("src/app.py",))

    metric = report.metrics.files[0]
    function = metric.functions[0]
    assert metric.import_fan_out == 13
    assert function.import_fan_out == 1
    assert _severities(report, "lean.function-risk") == set()


def test_oversized_function_with_broad_import_coupling_is_required(
    tmp_path: Path,
) -> None:
    _init_repo(tmp_path)
    imports = "\n".join(f"import dependency_{index}" for index in range(12))
    dependencies = ", ".join(f"dependency_{index}.VALUE" for index in range(12))
    body = "\n".join(f"    value += {index}" for index in range(51))
    _write(
        tmp_path,
        "src/app.py",
        f"{imports}\n\ndef _process():\n    value = sum(({dependencies}))\n{body}\n"
        "    return value\n",
    )

    report = _evaluate(tmp_path, scope=("src/app.py",))

    function = report.metrics.files[0].functions[0]
    assert function.import_fan_out == 12
    finding = next(
        item for item in report.findings if item.rule_id == "lean.function-risk"
    )
    assert "fan_out=12" in str(finding.measured_value)


def test_function_fan_out_includes_dependencies_in_function_defaults(
    tmp_path: Path,
) -> None:
    _init_repo(tmp_path)
    imports = "\n".join(f"import dependency_{index}" for index in range(12))
    defaults = ", ".join(
        f"value_{index}=dependency_{index}.VALUE" for index in range(12)
    )
    body = "\n".join(f"    total += value_{index % 12}" for index in range(51))
    _write(
        tmp_path,
        "src/app.py",
        f"{imports}\n\ndef _process({defaults}):\n"
        f"    total = 0\n{body}\n    return total\n",
    )

    report = _evaluate(tmp_path, scope=("src/app.py",))

    function = report.metrics.files[0].functions[0]
    assert function.import_fan_out == 12
    assert _severities(report, "lean.function-risk") == {FindingSeverity.REQUIRED}


