def test_oversized_complex_function_is_required(tmp_path: Path) -> None:
    _init_repo(tmp_path)
    branches = "\n".join(
        f"    if value == {index}:\n        value += 1" for index in range(12)
    )
    padding = "\n".join("    value += 1" for _ in range(30))
    _write(
        tmp_path,
        "src/app.py",
        f"def _process(value):\n{branches}\n{padding}\n    return value\n",
    )

    report = _evaluate(tmp_path, scope=("src/app.py",))

    assert FindingSeverity.REQUIRED in _severities(report, "lean.function-risk")
    assert report.status == LoopStatus.NEEDS_FIX


def test_enforcement_modes_have_distinct_required_finding_statuses(
    tmp_path: Path,
) -> None:
    _init_repo(tmp_path)
    _write(tmp_path, "src/api.py", "def unused_public():\n    return 1\n")

    report_mode = _evaluate(
        tmp_path, scope=("src/api.py",), policy=LeanPolicy(enforcement_mode="report")
    )
    warning_mode = _evaluate(
        tmp_path,
        scope=("src/api.py",),
        policy=LeanPolicy(enforcement_mode="warning"),
    )
    blocking_mode = _evaluate(
        tmp_path,
        scope=("src/api.py",),
        policy=LeanPolicy(enforcement_mode="blocking"),
    )

    assert report_mode.status == LoopStatus.PASSED
    assert warning_mode.status == LoopStatus.NEEDS_FIX
    assert blocking_mode.status == LoopStatus.BLOCKED


