def test_patch_source_metrics_use_patched_python_content(tmp_path: Path) -> None:
    _init_repo(tmp_path, {"src/app.py": "VALUE = 1\n"})
    _write(
        tmp_path,
        "src/app.py",
        "VALUE = 1\n\ndef _patched_value():\n    return VALUE\n",
    )
    patch_text = _git(tmp_path, "diff", "--binary", "--", "src/app.py")
    (tmp_path / "change.patch").write_bytes(
        (patch_text + "\n").replace("\n", "\r\n").encode("utf-8")
    )
    _git(tmp_path, "restore", "--worktree", "src/app.py")
    snapshot = build_source_snapshot(
        SourceSnapshotOptions(
            root=tmp_path,
            source_kind="patch",
            patch_file="change.patch",
        )
    )

    report = _evaluate(tmp_path, scope=("src/app.py",), snapshot=snapshot)

    metric = report.metrics.files[0]
    assert metric.added_lines == 3
    assert [item.symbol for item in metric.functions] == ["_patched_value"]
    assert report.status == LoopStatus.PASSED


def test_git_range_callers_are_read_from_frozen_head(tmp_path: Path) -> None:
    _init_repo(tmp_path)
    base = _git(tmp_path, "rev-parse", "HEAD")
    _write(tmp_path, "src/api.py", "def build_value():\n    return 1\n")
    _write(
        tmp_path,
        "src/callers.py",
        """from src.api import build_value

def _caller_a():
    return build_value()

def _caller_b():
    return build_value()

def _caller_c():
    return build_value()
""",
    )
    _git(tmp_path, "add", ".")
    _git(tmp_path, "commit", "-m", "add frozen callers")
    head = _git(tmp_path, "rev-parse", "HEAD")
    _git(tmp_path, "switch", "--detach", base)
    snapshot = build_source_snapshot(
        SourceSnapshotOptions(
            root=tmp_path,
            source_kind="local-git-range",
            base_ref=base,
            head_ref=head,
        )
    )

    report = _evaluate(tmp_path, scope=("src/*.py",), snapshot=snapshot)

    helper = report.metrics.files[0].functions[0]
    assert helper.symbol == "build_value"
    assert helper.caller_count == 3
    assert _severities(report, "lean.public-callers") == set()


