@pytest.mark.parametrize("kind", ("sync", "async"))
def test_later_iterator_advance_carries_plain_assignment_state(
    tmp_path: Path,
    kind: str,
) -> None:
    _init_repo(tmp_path)
    if kind == "sync":
        source = (
            "def broken():\n"
            "    yield 1\n"
            "    raise KeyError('broken')\n\n"
            "def factory():\n"
            "    loader = print\n"
            "    try:\n"
            "        for _ in broken():\n"
            "            loader = __import__\n"
            "        loader = print\n"
            "    except KeyError:\n"
            "        pass\n"
            "    return loader\n\n"
            "def _process():\n"
            "    return factory()('dependency')\n"
        )
    else:
        source = (
            "class Broken:\n"
            "    def __init__(self):\n"
            "        self.index = 0\n\n"
            "    def __aiter__(self):\n"
            "        return self\n\n"
            "    async def __anext__(self):\n"
            "        if self.index == 0:\n"
            "            self.index += 1\n"
            "            return 1\n"
            "        raise KeyError('broken')\n\n"
            "async def factory():\n"
            "    loader = print\n"
            "    try:\n"
            "        async for _ in Broken():\n"
            "            loader = __import__\n"
            "        loader = print\n"
            "    except KeyError:\n"
            "        pass\n"
            "    return loader\n\n"
            "async def _process():\n"
            "    return (await factory())('dependency')\n"
        )
    _write(tmp_path, "src/app.py", source)

    report = _evaluate(tmp_path, scope=("src/app.py",))

    assert _metric_capability(report, "_process") == "conservative"


