        "selected = [invoke, safe][1]\n"
        "selected(configure)\n\n"
        "class Dynamic:\n"
        "    @classmethod\n"
        "    def factory(value):\n"
        "        return value\n\n"
        "loader = Dynamic.__dict__['factory']\n\n"
